import { usePaginatedApi } from "@softimist/api";
function useFiles(dirID) {
  const { apiClient, config } = useFileManagerContext();
  const path = "/api/v1/files";
  const options = dirID ? { persist: false, params: { dir_id: dirID } } : { persist: false };
  const { data, ...rest } = usePaginatedApi(apiClient, path, options);
  const items = data?.map((item) => mapItem(item, config.assetBaseUrl)) || [];
  return {
    ...rest,
    data: items
  };
}
async function getFileItems(apiClient, assetBaseUrl, dirID) {
  const path = "/api/v1/files";
  const params = dirID ? { dir_id: dirID } : {};
  const res = await apiClient.get(path, { params });
  return res.data.map((item) => mapItem(item, assetBaseUrl));
}
function mapItem(item, assetBaseUrl) {
  if (item.item_type === "folder") {
    const dir = item;
    return {
      id: dir.id,
      name: dir.name,
      type: "folder",
      path: dir.id,
      created_at: dir.created_at
    };
  }
  const file = item;
  return getFileItemFromResponse(file, assetBaseUrl);
}
function getFileItemFromResponse(file, assetBaseUrl) {
  return {
    id: file.id,
    name: file.name,
    type: "file",
    path: file.id,
    size: file.size_in_bytes,
    mime_type: file.mime_type,
    url: getFileUrl(file.id, assetBaseUrl),
    created_at: file.created_at
  };
}

